sys_security_acl.script:
(function executeRule(current, previous) {

    if (gs.hasRole('x_1917769_servicen.admin')) {
        return true;
    }

    var userID = gs.getUserID();

    // Employee can edit only draft + own request
    if (gs.hasRole('x_1917769_servicen.employee_user')) {
        return current.requested_by.user.toString() == userID &&
               current.state == "Draft";
    }

    // Facility admin updates only assigned requests
    if (gs.hasRole('x_1917769_servicen.facility_admin')) {
        return current.facility_admin.toString() == userID;
    }

    // Branch manager updates only after facility approval
    if (gs.hasRole('x_1917769_servicen.manager')) {
        return current.state == "Facility Approved";
    }

    return false;

})(current, previous);
